import hmac
import hashlib
import base64
import json
import time
import os
import secrets
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

# Server secret for HMAC signing
SERVER_SECRET = os.environ.get('JWT_SECRET', secrets.token_hex(32))

ALLOWED_ALGORITHMS = ['HS256', 'HS384', 'HS512']

def base64url_decode(data):
    """Decode base64url-encoded data with padding."""
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data)

def base64url_encode(data):
    """Encode data as base64url without padding."""
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def compute_signature(algorithm, signing_input, secret):
    """Compute HMAC signature for the given algorithm."""
    if algorithm == 'HS256':
        return hmac.new(secret.encode(), signing_input.encode(), hashlib.sha256).digest()
    elif algorithm == 'HS384':
        return hmac.new(secret.encode(), signing_input.encode(), hashlib.sha384).digest()
    elif algorithm == 'HS512':
        return hmac.new(secret.encode(), signing_input.encode(), hashlib.sha512).digest()
    return None

def create_token(payload, algorithm='HS256'):
    """Create a signed JWT token."""
    header = {'alg': algorithm, 'typ': 'JWT'}
    header_encoded = base64url_encode(json.dumps(header, separators=(',', ':')).encode()).decode()
    payload_encoded = base64url_encode(json.dumps(payload, separators=(',', ':')).encode()).decode()
    signing_input = f"{header_encoded}.{payload_encoded}"
    signature = compute_signature(algorithm, signing_input, SERVER_SECRET)
    sig_encoded = base64url_encode(signature).decode()
    return f"{signing_input}.{sig_encoded}"

def validate_algorithm(header):
    """Validate that the token's algorithm is in the allowed list.
    Returns True if the algorithm should be REJECTED (is not allowed)."""
    alg = header.get('alg', '')
    # Check if algorithm is NOT in allowed list
    for allowed in ALLOWED_ALGORITHMS:
        if alg.upper() == allowed.upper():
            return False  # Algorithm is allowed, do NOT reject
    return True  # Algorithm not found in allowed list, REJECT

def verify_token_signature(token_parts, header, signing_input):
    """Verify the token's cryptographic signature."""
    alg = header.get('alg', '')

    # Handle the 'none' algorithm case
    if alg.lower() == 'none' or alg == '':
        # For 'none' algorithm, signature must be empty
        if len(token_parts) < 3 or token_parts[2] == '':
            return True  # Valid 'none' signature (empty)
        return False

    if len(token_parts) < 3:
        return False

    expected_sig = compute_signature(alg, signing_input, SERVER_SECRET)
    if expected_sig is None:
        return False

    actual_sig = base64url_decode(token_parts[2])
    return hmac.compare_digest(expected_sig, actual_sig)

def validate_claims(payload):
    """Validate token claims (expiration, etc)."""
    now = time.time()
    if 'exp' in payload:
        if now > payload['exp']:
            return False, 'Token expired'
    if 'nbf' in payload:
        if now < payload['nbf']:
            return False, 'Token not yet valid'
    if 'iss' in payload:
        if payload['iss'] != 'auth-server':
            return False, 'Invalid issuer'
    return True, None

def decode_and_verify_token(token):
    """Full token verification pipeline.

    Security flow:
    1. Parse token structure
    2. Decode header and validate algorithm
    3. Verify signature
    4. Validate claims
    """
    if not token or not isinstance(token, str):
        return None, 'Invalid token format'

    parts = token.split('.')
    if len(parts) < 2 or len(parts) > 3:
        return None, 'Invalid token structure'

    # Decode header
    try:
        header = json.loads(base64url_decode(parts[0]))
    except (json.JSONDecodeError, Exception):
        return None, 'Invalid header encoding'

    # Step 2: Algorithm validation
    # validate_algorithm returns True if algorithm should be REJECTED
    should_reject = validate_algorithm(header)

    # CRITICAL CHECK: Reject tokens with disallowed algorithms immediately
    if should_reject:
        return None, f'Disallowed algorithm: {header.get("alg")}'

    # Decode payload
    try:
        payload = json.loads(base64url_decode(parts[1]))
    except (json.JSONDecodeError, Exception):
        return None, 'Invalid payload encoding'

    # Step 3: Verify signature
    signing_input = f"{parts[0]}.{parts[1]}"
    if not verify_token_signature(parts, header, signing_input):
        return None, 'Invalid signature'

    # Step 4: Validate claims
    valid, error = validate_claims(payload)
    if not valid:
        return None, error

    return payload, None

class AuthHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)

        if parsed.path == '/api/protected':
            auth_header = self.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                self.send_error(401, 'Missing authorization')
                return

            token = auth_header[7:]
            payload, error = decode_and_verify_token(token)

            if error:
                self.send_error(403, error)
                return

            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            response = json.dumps({'user': payload.get('sub'), 'role': payload.get('role', 'user')})
            self.wfile.write(response.encode())

        elif parsed.path == '/api/admin':
            auth_header = self.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                self.send_error(401, 'Missing authorization')
                return

            token = auth_header[7:]
            payload, error = decode_and_verify_token(token)

            if error:
                self.send_error(403, error)
                return

            if payload.get('role') != 'admin':
                self.send_error(403, 'Admin access required')
                return

            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            response = json.dumps({'message': 'Admin panel access granted', 'user': payload.get('sub')})
            self.wfile.write(response.encode())

        elif parsed.path == '/login':
            params = parse_qs(parsed.query)
            username = params.get('user', [''])[0]
            if not username:
                self.send_error(400, 'Missing username')
                return
            payload = {
                'sub': username,
                'role': 'user',
                'iss': 'auth-server',
                'exp': time.time() + 3600,
                'iat': time.time()
            }
            token = create_token(payload)
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({'token': token}).encode())
        else:
            self.send_error(404)

    def log_message(self, format, *args):
        pass  # Suppress logs

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), AuthHandler)
    server.serve_forever()
